"""Local renderers for model-authored visuals. Nothing generated by a model is executed:
SVG is sanitized and rasterized by resvg; charts are declarative Vega-Lite specs."""

from __future__ import annotations

import copy
import io
import json
import textwrap
from pathlib import Path
from typing import Any

import resvg_py
import vl_convert as vlc
from lxml import etree
from PIL import Image, ImageDraw, ImageFont

from proseferno.images.base import ImageProviderError, to_png

# Inferno palette (dark → light) used for chart and diagram defaults.
INFERNO = ["#000004", "#1b0c41", "#4a0c6b", "#781c6d", "#a52c60", "#cf4446", "#ed6925", "#fb9b06", "#f7d13d", "#fcffa4"]
CHART_CATEGORY = ["#781c6d", "#ed6925", "#4a0c6b", "#fb9b06", "#cf4446", "#1b0c41", "#f7d13d", "#a52c60"]

SVG_NS = "http://www.w3.org/2000/svg"
_BANNED_TAGS = {"script", "foreignObject", "iframe", "object", "embed", "audio", "video"}


# -- SVG ---------------------------------------------------------------------


def sanitize_svg(svg: str) -> str:
    """Strip scripts, event handlers and external references from model-authored SVG."""
    parser = etree.XMLParser(resolve_entities=False, no_network=True, huge_tree=False, remove_comments=True)
    try:
        root = etree.fromstring(svg.strip().encode("utf-8"), parser)
    except etree.XMLSyntaxError as exc:
        raise ImageProviderError(f"The diagram SVG was not valid XML: {exc}") from exc
    if etree.QName(root).localname != "svg":
        raise ImageProviderError("The diagram must be an <svg> document.")
    for element in list(root.iter()):
        if not isinstance(element.tag, str):
            continue
        if etree.QName(element).localname in _BANNED_TAGS:
            element.getparent().remove(element)
            continue
        for attr in list(element.attrib):
            name = etree.QName(attr).localname.lower()
            value = element.attrib[attr].strip().lower()
            if (
                name.startswith("on")
                or (name == "href" and not value.startswith("#") and not value.startswith("data:image/"))
                or ("url(" in value and "url(#" not in value.replace(" ", ""))
            ):
                del element.attrib[attr]
        if etree.QName(element).localname == "style" and element.text and ("@import" in element.text or "url(http" in element.text):
            element.text = ""
    if "viewBox" not in root.attrib and not (root.get("width") and root.get("height")):
        root.set("viewBox", "0 0 1200 675")
    return etree.tostring(root, encoding="unicode")


def svg_to_png(svg: str, *, width: int = 1600, background: str | None = "#ffffff") -> tuple[bytes, int, int]:
    clean = sanitize_svg(svg)
    try:
        data = resvg_py.svg_to_bytes(svg_string=clean, width=width, background=background)
    except Exception as exc:
        raise ImageProviderError(f"Could not render the SVG: {exc}") from exc
    return to_png(bytes(data))


# -- Vega-Lite -----------------------------------------------------------------


def prepare_vega_spec(spec: dict[str, Any] | str) -> dict[str, Any]:
    if isinstance(spec, str):
        try:
            spec = json.loads(spec)
        except json.JSONDecodeError as exc:
            raise ImageProviderError(f"The chart spec was not valid JSON: {exc}") from exc
    if not isinstance(spec, dict):
        raise ImageProviderError("The chart spec must be a JSON object.")
    spec = copy.deepcopy(spec)
    _strip_remote_data(spec)
    spec.setdefault("$schema", "https://vega.github.io/schema/vega-lite/v5.json")
    spec.setdefault("width", 720)
    spec.setdefault("height", 405)
    spec.setdefault("background", "#ffffff")
    config = spec.setdefault("config", {})
    config.setdefault("range", {}).setdefault("category", CHART_CATEGORY)
    config.setdefault("mark", {}).setdefault("color", "#781c6d")
    config.setdefault("font", "Inter, Segoe UI, Helvetica, Arial, sans-serif")
    config.setdefault("title", {}).update({"fontSize": 18, "anchor": "start", "color": "#1b0c41"})
    config.setdefault("view", {}).setdefault("stroke", None)
    return spec


def _strip_remote_data(node: Any) -> None:
    """Charts must carry inline data; drop any URL-loaded data sources."""
    if isinstance(node, dict):
        data = node.get("data")
        if isinstance(data, dict) and "url" in data:
            raise ImageProviderError("Chart data must be inline values, not a URL.")
        for value in node.values():
            _strip_remote_data(value)
    elif isinstance(node, list):
        for value in node:
            _strip_remote_data(value)


def vega_to_png(spec: dict[str, Any] | str, *, scale: float = 2.0) -> tuple[bytes, int, int]:
    prepared = prepare_vega_spec(spec)
    try:
        data = vlc.vegalite_to_png(prepared, scale=scale)
    except Exception as exc:
        raise ImageProviderError(f"Could not render the chart: {exc}") from exc
    return to_png(bytes(data))


# -- Meme captions -------------------------------------------------------------

_FONT_CANDIDATES = [
    "C:/Windows/Fonts/impact.ttf",
    "C:/Windows/Fonts/ariblk.ttf",
    "C:/Windows/Fonts/arialbd.ttf",
    "/System/Library/Fonts/Supplemental/Impact.ttf",
    "/Library/Fonts/Impact.ttf",
    "/usr/share/fonts/truetype/msttcorefonts/Impact.ttf",
    "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
    "/usr/share/fonts/dejavu/DejaVuSans-Bold.ttf",
]


def _meme_font(size: int) -> ImageFont.FreeTypeFont | ImageFont.ImageFont:
    for candidate in _FONT_CANDIDATES:
        if Path(candidate).exists():
            return ImageFont.truetype(candidate, size)
    return ImageFont.load_default(size=size)


def add_meme_text(png: bytes, top: str, bottom: str) -> bytes:
    """Classic meme captions: white uppercase text with a black outline."""
    with Image.open(io.BytesIO(png)) as source:
        img = source.convert("RGB")
    draw = ImageDraw.Draw(img)
    width, height = img.size
    for text, at_top in ((top, True), (bottom, False)):
        text = (text or "").strip().upper()
        if not text:
            continue
        size = max(24, width // 14)
        while True:
            font = _meme_font(size)
            chars_per_line = max(8, int(width / (size * 0.62)))
            lines = textwrap.wrap(text, chars_per_line)[:3]
            widest = max(draw.textlength(line, font=font) for line in lines)
            if widest <= width * 0.94 or size <= 20:
                break
            size -= 4
        stroke = max(2, size // 14)
        line_height = int(size * 1.12)
        block = line_height * len(lines)
        y = int(height * 0.03) if at_top else height - block - int(height * 0.04)
        for line in lines:
            x = (width - draw.textlength(line, font=font)) / 2
            draw.text((x, y), line, font=font, fill="white", stroke_width=stroke, stroke_fill="black")
            y += line_height
    out = io.BytesIO()
    img.save(out, format="PNG")
    return out.getvalue()


# -- Screenshot placeholder ----------------------------------------------------


def placeholder_png(label: str, *, width: int = 1600, height: int = 900) -> tuple[bytes, int, int]:
    label = textwrap.shorten(label or "Add your screenshot here", 140)
    lines = textwrap.wrap(label, 48)[:3]
    tspans = "".join(f'<tspan x="{width // 2}" dy="{0 if i == 0 else 56}">{_xml_escape(line)}</tspan>' for i, line in enumerate(lines))
    svg = f"""<svg xmlns="{SVG_NS}" width="{width}" height="{height}" viewBox="0 0 {width} {height}">
  <rect width="100%" height="100%" fill="#fff8e6"/>
  <rect x="40" y="40" width="{width - 80}" height="{height - 80}" rx="28" fill="none" stroke="#ed6925" stroke-width="6" stroke-dasharray="24 16"/>
  <text x="{width // 2}" y="{height // 2 - 90}" text-anchor="middle" font-family="Segoe UI, Helvetica, Arial, sans-serif" font-size="44" font-weight="700" fill="#781c6d">Screenshot placeholder</text>
  <text x="{width // 2}" y="{height // 2}" text-anchor="middle" font-family="Segoe UI, Helvetica, Arial, sans-serif" font-size="40" fill="#1b0c41">{tspans}</text>
  <text x="{width // 2}" y="{height - 110}" text-anchor="middle" font-family="Segoe UI, Helvetica, Arial, sans-serif" font-size="30" fill="#a52c60">Use "Replace" in the editor to upload your real screenshot</text>
</svg>"""
    return svg_to_png(svg, width=width)


def _xml_escape(text: str) -> str:
    return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")
